# Let me analyze each task more carefully to understand the transformations

import json

with open("/workspace/DEMOS.json", "r") as f:
    demos = json.load(f)

# Group by task_id
tasks = {}
for demo in demos:
    tid = demo['task_id']
    if tid not in tasks:
        tasks[tid] = []
    tasks[tid].append((demo['input_examples'], demo['output_examples']))

# Analyze each task
for tid, examples in list(tasks.items())[:10]:
    print(f"\n=== Task {tid} ===")
    for j in range(min(3, len(examples))):
        inp, out = examples[j]
        print(f"\n  Example {j}: {inp} -> {out}")
        n_in = len(inp)
        n_out = len(out)

        # Try: is output = sorted unique elements?
        if sorted(out) == sorted(set(inp)):
            print(f"    => Output = sorted unique elements of input")

        # Try: is output = elements sorted descending?
        if out == sorted(inp, reverse=True):
            print(f"    => Output = sorted descending")

        # Try: is output = sorted ascending?
        if out == sorted(inp):
            print(f"    => Output = sorted ascending")

        # Try: output[i] = inp[len(inp)-1-i] (reverse)
        if out == list(reversed(inp)):
            print(f"    => Output = reversed input")

        # Try: each element maps to count of elements ≤ it?
        if len(out) == len(inp):
            counts = [sum(1 for x in inp if x <= v) for v in inp]
            if out == counts:
                print(f"    => Output = count of elements ≤ each element")

            counts2 = [sum(1 for x in inp if x < v) for v in inp]
            if out == counts2:
                print(f"    => Output = count of elements < each element")

            # Check differences
            diffs = [o - i for o, i in zip(out, inp)]
            if all(d == diffs[0] for d in diffs):
                print(f"    => Output = input + {diffs[0]}")

            diffs2 = [i - o for o, i in zip(out, inp)]
            if all(d == diffs2[0] for d in diffs2):
                print(f"    => Output = input - {diffs2[0]}")

            # Ratio check
            if inp[0] != 0 and out[0] != 0:
                ratio = out[0] / inp[0]
                if inp[1] != 0:
                    ratio2 = out[1] / inp[1]
                    if abs(ratio - ratio2) < 0.01:
                        print(f"    => Output ≈ input * {ratio}")

