# Let me take a different approach - look at ALL examples more systematically
# and also try to use the verifier with a brute force search

import json
from collections import Counter

with open("/workspace/DEMOS.json", "r") as f:
    demos = json.load(f)

# Get unique tasks with ALL examples
task_data = {}
for demo in demos:
    tid = demo['task_id']
    if tid not in task_data:
        task_data[tid] = {
            'hardness': demo['hardness'],
            'inputs': [],
            'outputs': []
        }
    task_data[tid]['inputs'].extend(demo['input_examples'])
    task_data[tid]['outputs'].extend(demo['output_examples'])

# Analyze each task
for tid in sorted(task_data.keys())[:15]:
    td = task_data[tid]
    print(f"\n=== Task {tid} (hardness={td['hardness']}) ===")

    for j in range(min(3, len(td['inputs']))):
        inp = td['inputs'][j]
        out = td['outputs'][j]
        n = len(inp)
        m = len(out)

        # Print summary
        print(f"  Example {j}: len={n}->{m}")
        print(f"    {inp[:5]}{'...' if n > 5 else ''} -> {out[:5]}{'...' if m > 5 else ''}")

        # Quick checks
        if n == m:
            # Same length - element-wise transform?
            if out == list(reversed(inp)):
                print(f"    -> REVERSE")
            elif sorted(out) == sorted(inp):
                print(f"    -> PERMUTATION of input")
            elif out == sorted(inp):
                print(f"    -> SORTED")
            elif out == sorted(inp, reverse=True):
                print(f"    -> SORTED REVERSE")
            elif len(set(out)) < len(set(inp)):
                print(f"    -> DEDUP?")
            else:
                # Check common transforms
                total = sum(inp)
                if out == [total]*n:
                    print(f"    -> ALL TOTAL")
                if out == [0]*m:
                    print(f"    -> ALL ZEROS")
                if all(o == 0 for o in out) and all(i != 0 for i in inp):
                    print(f"    -> ALL ZEROS")
        else:
            print(f"    (length changed)")

        # Check if it's a subset operation
        if all(o in set(inp) for o in out):
            print(f"    -> SUBSET of input values")

        if all(i in set(out) for i in inp):
            print(f"    -> SUPERSET (output contains all input)")

