"""
Symbolic solver for List Functions tasks.

Searches over compositions of list-transformation DSL primitives to find
programs that reproduce all given input/output examples.

The solver uses a multi-stage search:
1. Single-primitive programs (simple transforms)
2. Two-primitive compositions
3. Three-primitive compositions

Primitives include: identity, reverse, sort, dedup, slice, filter,
element-wise arithmetic, rotation, prepend/append, reduce, etc.
"""

import itertools
from collections import Counter, defaultdict
from functools import reduce
from typing import Any, Callable, Dict, List, Optional, Tuple


def _safe_product(lst: List[int], initial: int = 1) -> int:
    """Product of a list, handling empty list."""
    if not lst:
        return initial
    result = initial
    for x in lst:
        result *= x
    return result


def _coerce_output(result: Any) -> Optional[List[int]]:
    """Coerce a program output into a list of ints."""
    if result is None:
        return None
    if isinstance(result, tuple):
        result = list(result)
    if not isinstance(result, list):
        return None
    out = []
    for v in result:
        if isinstance(v, bool):
            return None
        if isinstance(v, int):
            out.append(v)
        elif isinstance(v, float) and v.is_integer():
            out.append(int(v))
        else:
            return None
    return out


# ============================================================
# PRIMITIVE OPERATIONS
# ============================================================

def _id(xs: List[int]) -> List[int]:
    return list(xs)


def _rev(xs: List[int]) -> List[int]:
    return list(reversed(xs))


def _sort_asc(xs: List[int]) -> List[int]:
    return sorted(xs)


def _sort_desc(xs: List[int]) -> List[int]:
    return sorted(xs, reverse=True)


def _dedup_first(xs: List[int]) -> List[int]:
    seen = set()
    result = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result


def _dedup_last(xs: List[int]) -> List[int]:
    seen = set()
    result = []
    for x in reversed(xs):
        if x not in seen:
            seen.add(x)
            result.append(x)
    return list(reversed(result))


def _unique(xs: List[int]) -> List[int]:
    """Only elements appearing exactly once, in order of first appearance."""
    c = Counter(xs)
    return [x for x in xs if c[x] == 1]


def _nonzero(xs: List[int]) -> List[int]:
    return [x for x in xs if x != 0]


def _positive(xs: List[int]) -> List[int]:
    return [x for x in xs if x > 0]


def _negatives(xs: List[int]) -> List[int]:
    return [x for x in xs if x < 0]


def _odds(xs: List[int]) -> List[int]:
    return [x for x in xs if x % 2 != 0]


def _evens(xs: List[int]) -> List[int]:
    return [x for x in xs if x % 2 == 0]


def _slice_first_n(xs: List[int], n: int) -> List[int]:
    return xs[:n]


def _slice_last_n(xs: List[int], n: int) -> List[int]:
    return xs[-n:] if n > 0 else []


def _slice_skip(xs: List[int], step: int) -> List[int]:
    return xs[::step]


def _slice_remove_idx(xs: List[int], idx: int) -> List[int]:
    if 0 <= idx < len(xs):
        return xs[:idx] + xs[idx+1:]
    return list(xs)


def _rotate_left(xs: List[int]) -> List[int]:
    if len(xs) <= 1:
        return list(xs)
    return xs[1:] + xs[:1]


def _rotate_right(xs: List[int]) -> List[int]:
    if len(xs) <= 1:
        return list(xs)
    return xs[-1:] + xs[:-1]


def _rotate_left_k(xs: List[int], k: int) -> List[int]:
    if len(xs) <= 1:
        return list(xs)
    k = k % len(xs) if len(xs) > 0 else 0
    return xs[k:] + xs[:k]


def _rotate_right_k(xs: List[int], k: int) -> List[int]:
    if len(xs) <= 1:
        return list(xs)
    k = k % len(xs) if len(xs) > 0 else 0
    return xs[-k:] + xs[:-k] if k > 0 else list(xs)


def _elem_add(xs: List[int], v: int) -> List[int]:
    return [x + v for x in xs]


def _elem_sub(xs: List[int], v: int) -> List[int]:
    return [x - v for x in xs]


def _elem_mul(xs: List[int], v: int) -> List[int]:
    return [x * v for x in xs]


def _elem_abs(xs: List[int]) -> List[int]:
    return [abs(x) for x in xs]


def _elem_max_val(xs: List[int]) -> List[int]:
    m = max(xs) if xs else 0
    return [m for _ in xs]


def _elem_min_val(xs: List[int]) -> List[int]:
    m = min(xs) if xs else 0
    return [m for _ in xs]


def _elem_add_sum(xs: List[int]) -> List[int]:
    s = sum(xs)
    return [x + s for x in xs]


def _elem_sub_sum(xs: List[int]) -> List[int]:
    s = sum(xs)
    return [x - s for x in xs]


def _cumsum(xs: List[int]) -> List[int]:
    result = []
    s = 0
    for x in xs:
        s += x
        result.append(s)
    return result


def _elem_rank(xs: List[int]) -> List[int]:
    """Rank of each element (1-indexed, ascending)."""
    if not xs:
        return []
    s = sorted(xs)
    return [s.index(x) + 1 for x in xs]


def _elem_count_le(xs: List[int]) -> List[int]:
    """Count of elements <= each element."""
    return [sum(1 for v in xs if v <= x) for x in xs]


def _elem_count_lt(xs: List[int]) -> List[int]:
    """Count of elements < each element."""
    return [sum(1 for v in xs if v < x) for x in xs]


def _elem_count_ge(xs: List[int]) -> List[int]:
    """Count of elements >= each element."""
    return [sum(1 for v in xs if v >= x) for x in xs]


def _elem_count_gt(xs: List[int]) -> List[int]:
    """Count of elements > each element."""
