    c = Counter(xs)
    seen = set()
    result = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            result.append(c[x])
    return result


def _freq_sort_count(xs: List[int]) -> List[int]:
    """Count of each unique element, in sorted order of element."""
    c = Counter(xs)
