# Dedup with position
def _dedup_even_pos(xs: List[int]) -> List[int]:
    """Keep elements at even positions after dedup."""
    seen = set()
    result = []
    for i, x in enumerate(xs):
        if x not in seen:
            seen.add(x)
            if i % 2 == 0:
                result.append(x)
    return result


def _dedup_odd_pos(xs: List[int]) -> List[int]:
    """Keep elements at odd positions after dedup."""
    seen = set()
    result = []
    for i, x in enumerate(xs):
        if x not in seen:
            seen.add(x)
            if i % 2 == 1:
                result.append(x)
    return result


def _first_occurrence_at_index(xs: List[int], idx: int) -> List[int]:
    """Get first occurrence of element at position idx."""
    if 0 <= idx < len(xs):
        return [xs[idx]]
    return []


