def _rev_sort_desc(xs: List[int]) -> List[int]:
    """Reverse sort (descending)."""
    return sorted(xs, reverse=True)


def _rev_sort_asc(xs: List[int]) -> List[int]:
    """Sort ascending, then reverse."""
    return sorted(xs, reverse=True)


def _sort_then_dedup(xs: List[int]) -> List[int]:
    """Sort then remove consecutive duplicates."""
    s = sorted(xs)
    result = []
    for x in s:
        if not result or x != result[-1]:
            result.append(x)
    return result


def _sort_then_dedup_first(xs: List[int]) -> List[int]:
    """Sort by first occurrence, then dedup."""
    order = {}
    for i, x in enumerate(xs):
        if x not in order:
            order[x] = i
    return sorted(set(xs), key=lambda x: order[x])


def _sort_unique_by_count_desc(xs: List[int]) -> List[int]:
    """Sort unique elements by count (descending), breaking ties by value."""
    c = Counter(xs)
    return sorted(set(xs), key=lambda x: (-c[x], x))


def _sort_unique_by_count_asc(xs: List[int]) -> List[int]:
    """Sort unique elements by count (ascending), breaking ties by value."""
    c = Counter(xs)
    return sorted(set(xs), key=lambda x: (c[x], x))


def _rotate_by_first_element(xs: List[int]) -> List[int]:
    """Rotate left by (first_element % len)."""
    if not xs:
        return []
    n = len(xs)
    if n <= 1:
        return list(xs)
    k = xs[0] % n
    return xs[k:] + xs[:k]


def _rotate_by_last_element(xs: List[int]) -> List[int]:
    """Rotate left by (last_element % len)."""
    if not xs:
        return []
    n = len(xs)
    if n <= 1:
        return list(xs)
    k = xs[-1] % n
    return xs[k:] + xs[:k]


def _rotate_left_count_nonzero(xs: List[int]) -> List[int]:
    """Rotate left by count of nonzero elements."""
    if not xs:
        return []
    n = len(xs)
    k = sum(1 for x in xs if x != 0) % n
    return xs[k:] + xs[:k]


def _rotate_right_count_nonzero(xs: List[int]) -> List[int]:
    """Rotate right by count of nonzero elements."""
    if not xs:
        return []
    n = len(xs)
    k = sum(1 for x in xs if x != 0) % n
    return xs[-k:] + xs[:-k] if k > 0 else list(xs)


def _sort_then_slice_first_n(xs: List[int], n: int) -> List[int]:
    return sorted(xs)[:n]


def _sort_then_slice_last_n(xs: List[int], n: int) -> List[int]:
    return sorted(xs)[-n:] if n > 0 else []


def _sort_then_dedup_then_slice(xs: List[int], n: int) -> List[int]:
    s = sorted(xs)
    deduped = []
    for x in s:
        if not deduped or x != deduped[-1]:
            deduped.append(x)
    return deduped[:n]


def _sort_desc_then_slice_first_n(xs: List[int], n: int) -> List[int]:
    return sorted(xs, reverse=True)[:n]


def _slice_first_n_then_rev(xs: List[int], n: int) -> List[int]:
    return list(reversed(xs[:n]))


def _slice_last_n_then_rev(xs: List[int], n: int) -> List[int]:
    return list(reversed(xs[-n:])) if n > 0 else []


def _filter_nonzero_then_sort(xs: List[int]) -> List[int]:
