def generate_primitives():
    """Generate all candidate primitive programs."""
    candidates = []

    # Single-arg primitives (no parameters)
    for name, func in UNARY_PRIMITIVES.items():
        candidates.append((f"{name}", lambda xs, f=func: f(xs)))

    for name, func in COMPOSITE_PRIMITIVES.items():
        candidates.append((f"{name}", lambda xs, f=func: f(xs)))

    # Primitives with parameters
    params = _get_all_candidate_params()
    for name, info in BINARY_PRIMITIVES.items():
        if callable(info[0]) and len(info[0].__code__.co_varnames) == 2:
            func = info[0]
            param_range = info[1]
            for p in param_range:
                try:
                    fn = func(xs=None, v=p) if 'v' in info[0].__code__.co_varnames else func(v=p)
                except:
                    pass
                # Try different signatures
                try:
                    def make_fn(f, val):
                        return lambda xs, _f=f, _v=val: _f(xs, _v)
                    candidates.append((f"{name}_{p}", make_fn(func, p)))
                except Exception:
                    pass
        elif callable(info[0]):
            func = info[0]
            param_range = info[1]
            for p in param_range:
                try:
                    def make_fn2(f, val):
                        return lambda xs, _f=f, _v=val: _f(_v)
                    candidates.append((f"{name}_{p}", make_fn2(func, p)))
                except Exception:
                    pass

    # Constant-output primitives (return a fixed list regardless of input)
    # These are useful for tasks like c101 where all outputs are the same
    # They get registered after seeing the examples

    return candidates


def _generate_const_programs(all_outputs) -> List[Tuple[str, Callable]]:
    """Generate constant-output programs from the output values."""
    # Check if all outputs are the same
    if all_outputs:
        first_output = all_outputs[0]
        # All same output?
        if all(o == first_output for o in all_outputs):
            return [(f"constant_{first_output[:5]}", lambda xs, out=first_output: list(out))]
    return []


def _generate_parametric_const_programs(all_outputs, param_range=None) -> List[Tuple[str, Callable]]:
    """Generate constant programs that might match a subset."""
    if param_range is None:
        param_range = _get_all_candidate_params()
    results = []
    for val in param_range:
        results.append((f"const_{val}", lambda xs, v=val: [v]))
    return results


def _generate_slice_programs(inputs, outputs) -> List[Tuple[str, Callable]]:
    """Generate slice programs that might match."""
    results = []
    for inp, out in zip(inputs, outputs):
        n_in = len(inp)
        n_out = len(out)
        if n_out <= n_in:
            # Try slicing from start
            for n in range(n_out, n_in + 1):
                if inp[:n] == out:
                    results.append((f"slice_first_{n}", lambda xs, _n=n: xs[:_n]))
            # Try slicing from end
            for n in range(n_out, n_in + 1):
                if inp[-n:] == out:
                    results.append((f"slice_last_{n}", lambda xs, _n=n: xs[-_n:]))
            # Try middle slice
            for start in range(n_in):
                for end in range(start + 1, n_in + 1):
                    if inp[start:end] == out:
                        results.append((f"slice_{start}_{end}", lambda xs, _s=start, _e=end: xs[_s:_e]))
    return results


def _generate_rotation_programs(inputs, outputs) -> List[Tuple[str, Callable]]:
    """Generate rotation programs that might match."""
    results = []
    for inp, out in zip(inputs, outputs):
        n = len(inp)
        if n == 0:
            continue
        for k in range(n):
            rotated = inp[k:] + inp[:k]
            if rotated == out:
                results.append((f"rotate_left_{k}", lambda xs, _k=k: xs[_k:] + xs[:_k] if _k > 0 else list(xs)))
            rotated_r = inp[-k:] + inp[:-k] if k > 0 else list(inp)
            if rotated_r == out:
                results.append((f"rotate_right_{k}", lambda xs, _k=k: xs[-_k:] + xs[:-_k] if _k > 0 else list(xs)))
    return results


def _generate_remove_programs(inputs, outputs) -> List[Tuple[str, Callable]]:
    """Generate remove-primitive programs."""
    results = []
    for inp, out in zip(inputs, outputs):
        n_in = len(inp)
        n_out = len(out)
        if n_in - n_out == 1:
            # Find which element was removed
            for i in range(n_in):
                candidate = inp[:i] + inp[i+1:]
                if candidate == out:
                    results.append((f"remove_idx_{i}", lambda xs, _i=i: xs[:_i] + xs[_i+1:]))
    return results


def _generate_filter_programs(inputs, outputs) -> List[Tuple[str, Callable]]:
    """Generate filter programs."""
    results = []
    # Check if output is input filtered by nonzero
    all_match = True
    for inp, out in zip(inputs, outputs):
        filtered = [x for x in inp if x != 0]
        if filtered != out:
            all_match = False
            break
    if all_match and len(inputs) > 0:
        results.append(("filter_nonzero", lambda xs: [x for x in xs if x != 0]))

    # Check if output is input filtered by positive
    all_match = True
    for inp, out in zip(inputs, outputs):
        filtered = [x for x in inp if x > 0]
        if filtered != out:
            all_match = False
            break
    if all_match and len(inputs) > 0:
        results.append(("filter_positive", lambda xs: [x for x in xs if x > 0]))

    return results


def _generate_prefix_suffix_programs(inputs, outputs) -> List[Tuple[str, Callable]]:
    """Generate programs that prepend/append constants."""
    results = []
    for inp, out in zip(inputs, outputs):
        # Check if out = [prefix...] + inp
        for i in range(len(out)):
            if out[i:] == inp:
                prefix = out[:i]
                results.append((f"prepend_const_{prefix}", lambda xs, _p=prefix: list(_p) + list(xs)))
                break
        # Check if out = inp + [suffix...]
        for i in range(len(out)):
            if out[:len(inp)] == inp:
                suffix = out[len(inp):]
                results.append((f"append_const_{suffix}", lambda xs, _s=suffix: list(xs) + list(_s)))
                break
    return results


def _generate_elementwise_programs(inputs, outputs) -> List[Tuple[str, Callable]]:
    """Generate element-wise transform programs."""
    results = []
    for inp, out in zip(inputs, outputs):
        if len(inp) != len(out):
            continue
        n = len(inp)
        if n == 0:
            continue

        # Check y = a*x + b for each element
        non_zero = [(x, y) for x, y in zip(inp, out) if x != 0]
        if non_zero:
            for i in range(min(2, len(non_zero))):
                x1, y1 = non_zero[i]
                for j in range(i+1, min(3, len(non_zero))):
                    x2, y2 = non_zero[j]
                    if x2 - x1 != 0:
                        a = (y2 - y1) / (x2 - x1)
                        if a == int(a):
                            a = int(a)
                            b = y1 - a * x1
                            if all(y == a * x + b for x, y in zip(inp, out)):
                                results.append((f"elem_{a}x+{b}", lambda xs, _a=a, _b=b: [_a*x + _b for x in xs]))

        # Check y = a*x (through origin)
        for i in range(min(2, len(inp))):
            x1, y1 = inp[i], out[i]
            if x1 != 0:
                for j in range(i+1, min(3, len(inp))):
                    x2, y2 = inp[j], out[j]
                    if x2 != 0:
                        a1 = y1 / x1 if x1 else None
                        a2 = y2 / x2 if x2 else None
                        if a1 is not None and a2 is not None and a1 == a2 and a1 == int(a1):
                            a = int(a1)
                            if all(y == a * x for x, y in zip(inp, out)):
                                results.append((f"elem_{a}x", lambda xs, _a=a: [_a*x for x in xs]))

        # Check y = x + b
        diffs = [y - x for x, y in zip(inp, out)]
        if all(d == diffs[0] for d in diffs):
            results.append((f"elem_+{diffs[0]}", lambda xs, _b=diffs[0]: [x + _b for x in xs]))

        # Check y = x - b
        diffs2 = [x - y for x, y in zip(inp, out)]
        if all(d == diffs2[0] for d in diffs2):
            results.append((f"elem_-{diffs2[0]}", lambda xs, _b=diffs2[0]: [x - _b for x in xs]))

        # Check y = x (identity)
        if all(y == x for x, y in zip(inp, out)):
            results.append(("elem_identity", lambda xs: list(xs)))

    return results


def _generate_frequency_programs(inputs, outputs) -> List[Tuple[str, Callable]]:
    """Generate frequency-count programs."""
    results = []
    # Check if output is frequency count in order of first appearance
    all_match = True
    for inp, out in zip(inputs, outputs):
        c = Counter(inp)
        seen = set()
        freqs = []
        for x in inp:
            if x not in seen:
                seen.add(x)
                freqs.append(c[x])
        if freqs != out:
            all_match = False
            break
    if all_match and len(inputs) > 0:
        results.append(("freq_count", lambda xs: _freq_count(xs)))
    return results


def _generate_reduction_programs(inputs, outputs) -> List[Tuple[str, Callable]]:
    """Generate reduce-to-single-value programs."""
    results = []
    for inp, out in zip(inputs, outputs):
        if len(out) == 1 and len(inp) >= 1:
            val = out[0]
            # Try product
            if _safe_product(inp, 1) == val:
                results.append(("reduce_product", lambda xs: [_safe_product(xs, 1)]))
            # Try sum
            if sum(inp) == val:
                results.append(("reduce_sum", lambda xs: [sum(xs)]))
            # Try min
            if min(inp) == val:
                results.append(("reduce_min", lambda xs: [min(xs)]))
            # Try max
            if max(inp) == val:
                results.append(("reduce_max", lambda xs: [max(xs)]))
            # Try number of unique elements
            if len(set(inp)) == val:
                results.append(("reduce_unique_count", lambda xs: [len(set(xs))]))
            # Try count of elements matching a value
            for v in set(inp):
                if sum(1 for x in inp if x == v) == val:
                    results.append((f"count_{v}", lambda xs, _v=v: [sum(1 for x in xs if x == _v)]))
            # Try count of elements in some range
            if inp and max(inp) <= 10:
                for lo in range(max(inp) + 1):
                    for hi in range(lo, max(inp) + 1):
                        count = sum(1 for x in inp if lo <= x <= hi)
                        if count == val:
                            results.append((f"count_{"lo","hi"}", lambda xs, _lo=lo, _hi=hi: [sum(1 for x in xs if _lo <= x <= _hi)]))
            # Try count of odd elements
            if sum(1 for x in inp if x % 2 != 0) == val:
                results.append(("count_odd", lambda xs: [sum(1 for x in xs if x % 2 != 0)]))
            # Try count of even elements
            if sum(1 for x in inp if x % 2 == 0) == val:
                results.append(("count_even", lambda xs: [sum(1 for x in xs if x % 2 == 0)]))
    return results


def _generate_sort_programs(inputs, outputs) -> List[Tuple[str, Callable]]:
    """Generate sort-related programs."""
    results = []
    for inp, out in zip(inputs, outputs):
        # Sorted ascending
        if sorted(inp) == out:
            results.append(("sort_asc", lambda xs: sorted(xs)))
        # Sorted descending
        if sorted(inp, reverse=True) == out:
            results.append(("sort_desc", lambda xs: sorted(xs, reverse=True)))
    return results


def _generate_dedup_programs(inputs, outputs) -> List[Tuple[str, Callable]]:
    """Generate dedup programs."""
    results = []
    for inp, out in zip(inputs, outputs):
        # Dedup preserving first occurrence
        seen = set()
        deduped = []
        for x in inp:
            if x not in seen:
                seen.add(x)
                deduped.append(x)
        if deduped == out:
            results.append(("dedup_first", lambda xs: _dedup_first(xs)))
    return results


def _generate_const_output_programs(inputs, outputs) -> List[Tuple[str, Callable]]:
    """Generate programs that always return the same output."""
    if all(o == outputs[0] for o in outputs):
        return [(f"constant", lambda xs, o=outputs[0]: list(o))]
    return []


def _generate_concat_programs(inputs, outputs) -> List[Tuple[str, Callable]]:
    """Generate concat programs (prefix + input + suffix)."""
    results = []
    # Check: prefix + input == output
    for inp, out in zip(inputs, outputs):
        if len(out) >= len(inp):
            prefix = out[:len(inp)]
            if prefix == inp:
                suffix = out[len(inp):]
                results.append((f"append_{suffix}", lambda xs, _s=suffix: list(xs) + list(_s)))

    # Check: input + suffix == output
    for inp, out in zip(inputs, outputs):
        if len(out) >= len(inp):
            suffix = out[-(len(out)-len(inp)):]
            if out[:len(inp)] == inp:
                prefix = out[:len(inp)]
                # Already handled above
                break

    # Check: prefix + input == output (with same prefix for all examples)
    if inputs:
        first_prefix = outputs[0][:len(inputs[0])]
        all_match = all(
            out[:len(inp)] == inp and out[len(inp):] == outputs[0][len(inp):]
            for inp, out in zip(inputs, outputs)
        )
        if all_match:
            prefix = outputs[0][:len(inputs[0])]
            suffix = outputs[0][len(inputs[0]):]
            results.append((f"concat_{prefix}_{suffix}", lambda xs, _p=prefix, _s=suffix: list(_p) + list(xs) + list(_s)))

    # Check: constant_prefix + input == output
    if inputs:
        prefix = outputs[0][:len(inputs[0])]
        all_match = all(
            out[:len(inp)] == prefix
            for inp, out in zip(inputs, outputs)
        )
        if all_match:
            suffixes = set()
            for inp, out in zip(inputs, outputs):
                suffixes.add(tuple(out[len(inp):]))
            if len(suffixes) == 1:
                suffix = list(suffixes.pop())
                results.append((f"const_prefix_{prefix}", lambda xs, _p=prefix, _s=suffix: list(_p) + list(xs) + list(_s)))
                results.append((f"prefix_{prefix}", lambda xs, _p=prefix: list(_p) + list(xs)))
                results.append((f"suffix_{suffix}", lambda xs, _s=suffix: list(xs) + list(_s)))

    return results


def _generate_pattern_programs(inputs, outputs) -> List[Tuple[str, Callable]]:
    """Generate pattern-based programs."""
    results = []

    # Check c109 pattern: single element -> identity, multiple -> product
    single_match = all(len(inp) == 1 and out == inp for inp, out in zip(inputs, outputs) if len(inp) == 1)
    multi_match = all(len(inp) > 1 and out == [_safe_product(inp)] for inp, out in zip(inputs, outputs) if len(inp) > 1)
    if single_match and multi_match:
        results.append(("product_or_identity", lambda xs: [_safe_product(xs, 1)] if len(xs) > 1 else list(xs)))

    # Check: rotate based on first element being 0
    zero_match = all(
        (inp[0] == 0 and _rotate_right_k(inp, 1) == out) or
        (inp[0] != 0 and _rotate_left_k(inp, 1) == out)
        for inp, out in zip(inputs, outputs)
        if len(inp) > 1
    )
    # More general: rotate by first element mod len (when first != 0)
    rot_match = all(
        (len(inp) > 1 and _rotate_left_by_k(inp, inp[0] % len(inp)) == out)
        for inp, out in zip(inputs, outputs)
    )
    if rot_match:
        results.append(("rotate_left_first_mod", lambda xs: _rotate_left_by_k(xs, xs[0] % len(xs)) if xs else []))

    return results


