def solve_listfn(examples: List[Tuple[List[int], List[int]]], K: int = 5) -> Dict[str, Any]:
    """
    Solve a List Functions task.

    Args:
        examples: list of (input_list, output_list) pairs
        K: number of top programs to return if no exact match

    Returns:
        dict with "success" (bool) and "program" (source string or callable)
    """
    inputs = [inp for inp, _ in examples]
    outputs = [out for _, out in examples]

    # First, try to find an exact match with pattern-based programs
    candidate_funcs: List[Tuple[str, Callable, float]] = []

    # Stage 0: Check for constant output
    const_progs = _generate_const_output_programs(inputs, outputs)
    for name, fn in const_progs:
        if _try_program(fn, inputs, outputs):
            return {"success": True, "program": name}

    # Stage 1: Check for pattern-based programs
    pattern_progs = _generate_pattern_programs(inputs, outputs)
    for name, fn in pattern_progs:
        if _try_program(fn, inputs, outputs):
            return {"success": True, "program": fn}

    # Stage 2: Check for element-wise programs
    elem_progs = _generate_elementwise_programs(inputs, outputs)
    for name, fn in elem_progs:
        if _try_program(fn, inputs, outputs):
            return {"success": True, "program": fn}

    # Stage 3: Check for frequency programs
    freq_progs = _generate_frequency_programs(inputs, outputs)
    for name, fn in freq_progs:
        if _try_program(fn, inputs, outputs):
            return {"success": True, "program": fn}

    # Stage 4: Check for reduction programs
    red_progs = _generate_reduction_programs(inputs, outputs)
    for name, fn in red_progs:
        if _try_program(fn, inputs, outputs):
            return {"success": True, "program": fn}

    # Stage 5: Check for slice programs
    slice_progs = _generate_slice_programs(inputs, outputs)
    for name, fn in slice_progs:
        if _try_program(fn, inputs, outputs):
            return {"success": True, "program": fn}

    # Stage 6: Check for rotation programs
    rot_progs = _generate_rotation_programs(inputs, outputs)
    for name, fn in rot_progs:
        if _try_program(fn, inputs, outputs):
            return {"success": True, "program": fn}

    # Stage 7: Check for filter programs
    filt_progs = _generate_filter_programs(inputs, outputs)
    for name, fn in filt_progs:
        if _try_program(fn, inputs, outputs):
            return {"success": True, "program": fn}

    # Stage 8: Check for concat programs
    concat_progs = _generate_concat_programs(inputs, outputs)
    for name, fn in concat_progs:
        if _try_program(fn, inputs, outputs):
            return {"success": True, "program": fn}

    # Stage 9: Check for sort programs
    sort_progs = _generate_sort_programs(inputs, outputs)
    for name, fn in sort_progs:
        if _try_program(fn, inputs, outputs):
            return {"success": True, "program": fn}

    # Stage 10: Check for dedup programs
    dedup_progs = _generate_dedup_programs(inputs, outputs)
    for name, fn in dedup_progs:
        if _try_program(fn, inputs, outputs):
            return {"success": True, "program": fn}

    # Stage 11: Remove programs
    remove_progs = _generate_remove_programs(inputs, outputs)
    for name, fn in remove_progs:
        if _try_program(fn, inputs, outputs):
            return {"success": True, "program": fn}

    # Stage 12: Search over unary primitives
    for name, func in UNARY_PRIMITIVES.items():
        if _try_program(func, inputs, outputs):
            return {"success": True, "program": func}

    # Stage 13: Two-primitive compositions
    unary_funcs = list(UNARY_PRIMITIVES.values())
    all_funcs = [f for f in unary_funcs if f not in CONSTANT_PRIMITIVES.values()]

    for f1 in all_funcs:
        for f2 in all_funcs:
            def compose(f1, f2, xs):
                intermediate = _apply_primitive(f1, xs)
                if intermediate is None:
                    return None
                return _apply_primitive(f2, intermediate)
            fn = lambda xs, _f1=f1, _f2=f2: compose(_f1, _f2, xs)
            if _try_program(fn, inputs, outputs):
                return {"success": True, "program": fn}

    # Stage 14: Two-primitive with parametric functions
    # Build a list of parameterized functions from the examples
    param_funcs = []

    # Generate parametric versions for common parameters
    test_params = _get_all_candidate_params()
    for name, info in BINARY_PRIMITIVES.items():
        func = info[0] if isinstance(info, tuple) else info
        param_range = info[1] if isinstance(info, tuple) else range(-5, 15)

        for p in param_range:
            try:
                # Try different function signatures
                if name == "elem_add":
                    fn = lambda xs, _v=p: [_v + x for x in xs]
                elif name == "elem_sub":
                    fn = lambda xs, _v=p: [x - _v for x in xs]
                elif name == "elem_mul":
                    fn = lambda xs, _v=p: [x * _v for x in xs]
                elif name == "slice_first_n":
                    fn = lambda xs, _n=p: xs[:_n]
                elif name == "slice_last_n":
                    fn = lambda xs, _n=p: xs[-_n:] if _n > 0 else []
                elif name == "slice_skip":
                    fn = lambda xs, _n=p: xs[::_n]
                elif name == "slice_remove_idx":
                    fn = lambda xs, _i=p: xs[:_i] + xs[_i+1:]
                elif name == "rotate_left_k":
                    fn = lambda xs, _k=p: xs[_k:] + xs[:_k] if _k > 0 else list(xs)
                elif name == "rotate_right_k":
                    fn = lambda xs, _k=p: xs[-_k:] + xs[:-_k] if _k > 0 else list(xs)
                elif name == "prepend_const":
                    fn = lambda xs, _v=p: [_v] + list(xs)
                elif name == "append_const":
                    fn = lambda xs, _v=p: list(xs) + [_v]
                elif name == "count_leq_n":
