def _append_min(xs: List[int]) -> List[int]:
    if not xs:
        return list(xs)
    return list(xs) + [min(xs)]


def _prepend_max(xs: List[int]) -> List[int]:
    if not xs:
        return list(xs)
    return [max(xs)] + list(xs)


def _append_max(xs: List[int]) -> List[int]:
    if not xs:
        return list(xs) + [max(xs)]


def _prepend_range(n: int) -> Callable[[List[int]], List[int]]:
    def fn(xs):
        return list(range(n)) + list(xs)
    return fn


def _append_range(n: int) -> Callable[[List[int]], List[int]]:
    def fn(xs):
        return list(xs) + list(range(n))
    return fn


# Range generation primitives
def _gen_range_start(xs: List[int]) -> List[int]:
    """Generate [0, 1, ..., len(xs)-1]."""
    return list(range(len(xs)))


def _gen_range_end(n: int) -> List[int]:
    """Generate [0, 1, ..., n-1]."""
    return list(range(n))


def _gen_range_max(xs: List[int]) -> List[int]:
    """Generate [0, 1, ..., max(xs)]."""
    if not xs:
        return []
    return list(range(max(xs) + 1))


def _gen_range_sum(xs: List[int]) -> List[int]:
    """Generate [0, 1, ..., sum(xs)]."""
    return list(range(sum(xs) + 1))


# Dedup with position
def _dedup_even_pos(xs: List[int]) -> List[int]:
    """Keep elements at even positions after dedup."""
    seen = set()
    result = []
    for i, x in enumerate(xs):
        if x not in seen:
            seen.add(x)
            if i % 2 == 0:
                result.append(x)
    return result


def _dedup_odd_pos(xs: List[int]) -> List[int]:
    """Keep elements at odd positions after dedup."""
    seen = set()
    result = []
    for i, x in enumerate(xs):
        if x not in seen:
            seen.add(x)
            if i % 2 == 1:
                result.append(x)
    return result


def _first_occurrence_at_index(xs: List[int], idx: int) -> List[int]:
    """Get first occurrence of element at position idx."""
    if 0 <= idx < len(xs):
        return [xs[idx]]
    return []


# ============================================================
# COMPOSITE OPERATIONS (pre-defined useful compositions)
# ============================================================

def _rev_sort_desc(xs: List[int]) -> List[int]:
    """Reverse sort (descending)."""
    return sorted(xs, reverse=True)


def _rev_sort_asc(xs: List[int]) -> List[int]:
    """Sort ascending, then reverse."""
    return sorted(xs, reverse=True)


def _sort_then_dedup(xs: List[int]) -> List[int]:
    """Sort then remove consecutive duplicates."""
    s = sorted(xs)
    result = []
    for x in s:
        if not result or x != result[-1]:
            result.append(x)
    return result


def _sort_then_dedup_first(xs: List[int]) -> List[int]:
    """Sort by first occurrence, then dedup."""
    order = {}
    for i, x in enumerate(xs):
        if x not in order:
            order[x] = i
    return sorted(set(xs), key=lambda x: order[x])


def _sort_unique_by_count_desc(xs: List[int]) -> List[int]:
    """Sort unique elements by count (descending), breaking ties by value."""
    c = Counter(xs)
    return sorted(set(xs), key=lambda x: (-c[x], x))


def _sort_unique_by_count_asc(xs: List[int]) -> List[int]:
    """Sort unique elements by count (ascending), breaking ties by value."""
    c = Counter(xs)
    return sorted(set(xs), key=lambda x: (c[x], x))


def _rotate_by_first_element(xs: List[int]) -> List[int]:
    """Rotate left by (first_element % len)."""
    if not xs:
        return []
    n = len(xs)
    if n <= 1:
        return list(xs)
    k = xs[0] % n
    return xs[k:] + xs[:k]


def _rotate_by_last_element(xs: List[int]) -> List[int]:
    """Rotate left by (last_element % len)."""
    if not xs:
        return []
    n = len(xs)
    if n <= 1:
        return list(xs)
    k = xs[-1] % n
    return xs[k:] + xs[:k]


def _rotate_left_count_nonzero(xs: List[int]) -> List[int]:
    """Rotate left by count of nonzero elements."""
    if not xs:
        return []
    n = len(xs)
    k = sum(1 for x in xs if x != 0) % n
    return xs[k:] + xs[:k]


def _rotate_right_count_nonzero(xs: List[int]) -> List[int]:
    """Rotate right by count of nonzero elements."""
    if not xs:
        return []
    n = len(xs)
    k = sum(1 for x in xs if x != 0) % n
    return xs[-k:] + xs[:-k] if k > 0 else list(xs)


def _sort_then_slice_first_n(xs: List[int], n: int) -> List[int]:
    return sorted(xs)[:n]


def _sort_then_slice_last_n(xs: List[int], n: int) -> List[int]:
    return sorted(xs)[-n:] if n > 0 else []


def _sort_then_dedup_then_slice(xs: List[int], n: int) -> List[int]:
    s = sorted(xs)
    deduped = []
    for x in s:
        if not deduped or x != deduped[-1]:
            deduped.append(x)
    return deduped[:n]


def _sort_desc_then_slice_first_n(xs: List[int], n: int) -> List[int]:
    return sorted(xs, reverse=True)[:n]


def _slice_first_n_then_rev(xs: List[int], n: int) -> List[int]:
    return list(reversed(xs[:n]))


def _slice_last_n_then_rev(xs: List[int], n: int) -> List[int]:
    return list(reversed(xs[-n:])) if n > 0 else []


def _filter_nonzero_then_sort(xs: List[int]) -> List[int]:
    return sorted(x for x in xs if x != 0)


def _filter_nonzero_then_sort_desc(xs: List[int]) -> List[int]:
    return sorted((x for x in xs if x != 0), reverse=True)


def _filter_positive_then_sort(xs: List[int]) -> List[int]:
    return sorted(x for x in xs if x > 0)


def _filter_odd_then_sort(xs: List[int]) -> List[int]:
    return sorted(x for x in xs if x % 2 != 0)


def _filter_even_then_sort(xs: List[int]) -> List[int]:
    return sorted(x for x in xs if x % 2 == 0)


def _dedup_first_then_sort(xs: List[int]) -> List[int]:
    return sorted(_dedup_first(xs))


def _dedup_first_then_sort_desc(xs: List[int]) -> List[int]:
    return sorted(_dedup_first(xs), reverse=True)


def _elem_mul_max(xs: List[int]) -> List[int]:
    m = max(xs) if xs else 1
    return [x * m for x in xs]


def _elem_mul_min(xs: List[int]) -> List[int]:
    m = min(xs) if xs else 1
    return [x * m for x in xs]


def _elem_abs_then_sort(xs: List[int]) -> List[int]:
    return sorted(abs(x) for x in xs)


def _elem_abs_then_sort_desc(xs: List[int]) -> List[int]:
    return sorted((abs(x) for x in xs), reverse=True)


def _freq_count_sorted_by_elem(xs: List[int]) -> List[int]:
    """Count of each unique element, in sorted order."""
    c = Counter(xs)
    return [c[k] for k in sorted(c)]


def _count_unique_elements(xs: List[int]) -> List[int]:
    return [len(set(xs))]


def _count_even_elements(xs: List[int]) -> List[int]:
    return [sum(1 for x in xs if x % 2 == 0)]


def _count_odd_elements(xs: List[int]) -> List[int]:
    return [sum(1 for x in xs if x % 2 != 0)]


def _count_max_count(xs: List[int]) -> List[int]:
    """Count of the most frequent element."""
    if not xs:
        return [0]
    return [Counter(xs).most_common(1)[0][1]]


def _count_min_count(xs: List[int]) -> List[int]:
    """Count of the least frequent element."""
    if not xs:
        return [0]
    c = Counter(xs)
    return [min(c.values())]


def _count_median(xs: List[int]) -> List[int]:
    """Count of the median element (most common middle)."""
    if not xs:
        return [0]
    s = sorted(xs)
    n = len(s)
    if n % 2 == 1:
        median = s[n // 2]
    else:
        median = (s[n // 2 - 1] + s[n // 2]) // 2
    return [sum(1 for x in s if x == median)]


def _count_range_0_to_max(xs: List[int]) -> List[int]:
    """Count elements in range [0, max]."""
    if not xs:
        return [0]
    return [sum(1 for x in xs if 0 <= x <= max(xs))]


def _count_missing_in_0_to_max(xs: List[int]) -> List[int]:
    """Count of numbers missing from 0..max."""
    if not xs:
        return [0]
    mx = max(xs)
    present = set(xs)
    return [mx + 1 - len([x for x in range(mx + 1) if x in present])]


def _first_last_sum(xs: List[int]) -> List[int]:
    if len(xs) == 0:
        return [0]
    if len(xs) == 1:
        return [xs[0]]
    return [xs[0] + xs[-1]]


def _first_last_diff(xs: List[int]) -> List[int]:
    if len(xs) == 0:
        return [0]
    if len(xs) == 1:
        return [xs[0]]
    return [xs[0] - xs[-1]]


def _second_element(xs: List[int]) -> List[int]:
    if len(xs) > 1:
        return [xs[1]]
    return [0]


def _penultimate_element(xs: List[int]) -> List[int]:
    if len(xs) > 1:
        return [xs[-2]]
    return [0]


def _remove_duplicates_preserve_order(xs: List[int]) -> List[int]:
    seen = set()
    result = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result


def _remove_first_half(xs: List[int]) -> List[int]:
    n = len(xs)
    return xs[n // 2:] if n > 0 else []


def _remove_second_half(xs: List[int]) -> List[int]:
    n = len(xs)
    return xs[:n // 2] if n > 0 else []


def _remove_element_at_idx(xs: List[int], idx: int) -> List[int]:
    if 0 <= idx < len(xs):
        return xs[:idx] + xs[idx+1:]
    return list(xs)


def _remove_first_occurrence(xs: List[int], val: int) -> List[int]:
    result = list(xs)
    try:
        result.remove(val)
    except ValueError:
        pass
    return result


def _remove_last_occurrence(xs: List[int], val: int) -> List[int]:
    for i in range(len(xs) - 1, -1, -1):
        if xs[i] == val:
            return xs[:i] + xs[i+1:]
    return list(xs)


def _keep_first_n_unique(xs: List[int], n: int) -> List[int]:
    """Keep only first n unique elements."""
    seen = set()
    result = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            result.append(x)
            if len(seen) >= n:
                break
    return result


def _filter_greater_than_min(xs: List[int]) -> List[int]:
    if not xs:
        return []
    mn = min(xs)
    return [x for x in xs if x > mn]


def _filter_less_than_max(xs: List[int]) -> List[int]:
    if not xs:
        return []
    mx = max(xs)
    return [x for x in xs if x < mx]


def _filter_between_min_max(xs: List[int]) -> List[int]:
    if not xs:
        return []
    mn, mx = min(xs), max(xs)
    return [x for x in xs if mn < x < mx]


def _swap_first_last(xs: List[int]) -> List[int]:
    if len(xs) <= 1:
        return list(xs)
    result = list(xs)
    result[0], result[-1] = result[-1], result[0]
    return result


def _insert_value_at_idx(xs: List[int], val: int, idx: int) -> List[int]:
    if idx < 0:
        idx = 0
    if idx > len(xs):
        idx = len(xs)
    return xs[:idx] + [val] + xs[idx:]


def _repeat_last_n(xs: List[int], n: int) -> List[int]:
    """Repeat the last n elements."""
    if len(xs) < n:
        return list(xs) * ((n // len(xs)) + 1)
    return xs + xs[-n:]


def _prepend_last_elem(xs: List[int]) -> List[int]:
    if not xs:
        return list(xs)
    return [xs[-1]] + list(xs)


def _append_first_elem(xs: List[int]) -> List[int]:
    if not xs:
        return list(xs)
    return list(xs) + [xs[0]]


def _prepend_last_two(xs: List[int]) -> List[int]:
    if len(xs) < 2:
        return list(xs)
    return [xs[-2], xs[-1]] + list(xs)


def _append_first_two(xs: List[int]) -> List[int]:
    if len(xs) < 2:
        return list(xs) + list(xs)
    return list(xs) + [xs[0], xs[1]]


def _prepend_max_append_min(xs: List[int]) -> List[int]:
    if not xs:
        return list(xs)
    return [max(xs)] + list(xs) + [min(xs)]


def _prepend_min_append_max(xs: List[int]) -> List[int]:
    if not xs:
        return list(xs)
    return [min(xs)] + list(xs) + [max(xs)]


def _rotate_right_by_k(xs: List[int], k: int) -> List[int]:
    if not xs:
        return []
    n = len(xs)
    k = k % n
    return xs[-k:] + xs[:-k] if k > 0 else list(xs)


def _rotate_left_by_k(xs: List[int], k: int) -> List[int]:
    if not xs:
        return []
    n = len(xs)
    k = k % n
    return xs[k:] + xs[:k]


def _remove_element_at_middle(xs: List[int]) -> List[int]:
    n = len(xs)
    if n <= 1:
        return list(xs)
    mid = n // 2
    return xs[:mid] + xs[mid+1:]


def _remove_duplicates_of_most_common(xs: List[int]) -> List[int]:
    if not xs:
        return []
    c = Counter(xs)
    most_common = c.most_common(1)[0][0]
    return [x for x in xs if x != most_common]


def _remove_duplicates_of_least_common(xs: List[int]) -> List[int]:
    if not xs:
        return []
    c = Counter(xs)
    min_count = min(c.values())
    least_common = [k for k, v in c.items() if v == min_count]
    return [x for x in xs if x not in least_common]


def _count_elements_equal_to_mode(xs: List[int]) -> List[int]:
    """Count how many elements equal the most common value."""
    if not xs:
        return [0]
    c = Counter(xs)
    mode = c.most_common(1)[0][0]
    return [c[mode]]


def _count_elements_equal_to_median(xs: List[int]) -> List[int]:
    """Count elements equal to the median value."""
    if not xs:
        return [0]
    s = sorted(xs)
    n = len(s)
    if n % 2 == 1:
        med = s[n // 2]
    else:
        med = (s[n // 2 - 1] + s[n // 2]) // 2
    return [sum(1 for x in s if x == med)]


