def _make_const_list(val: int) -> List[int]:
    """Create a constant list [val]."""
    return [val]


def _get_all_candidate_params() -> List[int]:
    """Get range of parameter values to try."""
    return list(range(-5, 15))


def _apply_primitive(func: Callable, xs: List[int]) -> List[int]:
    """Apply a primitive function to input list."""
    try:
        result = func(xs)
        return _coerce_output(result)
    except Exception:
        return None


def _score_program(program: Callable, inputs: List[List[int]],
                   outputs: List[List[int]]) -> Tuple[float, List[str]]:
    """Score a program against examples."""
    correct = 0
    mismatches = []
    for inp, expected in zip(inputs, outputs):
        try:
            got = _coerce_output(program(list(inp)))
        except Exception as e:
            got = None
            if len(mismatches) < 3:
                mismatches.append(f"{inp} -> ERROR: {e}")
            continue
        if got is not None and got == list(expected):
            correct += 1
        else:
            if len(mismatches) < 5:
                mismatches.append(f"{inp[:10]}... -> {got} (expected {expected[:10]})")
    return correct / len(inputs), mismatches


def _program_source(code_fn) -> str:
    """Generate a source string for a program function."""
    return f"""def program(xs):
    return {code_fn.__name__}(xs)"""


def _try_program(program: Callable, inputs: List[List[int]],
                 outputs: List[List[int]]) -> bool:
    """Check if a program matches all examples."""
    for inp, expected in zip(inputs, outputs):
        try:
            got = _coerce_output(program(list(inp)))
            if got != list(expected):
                return False
        except Exception:
            return False
    return True


