"""
Symbolic solver for List Functions tasks.

Searches over compositions of list-transformation DSL primitives to find
programs that reproduce all given input/output examples.
"""

from collections import Counter
from functools import reduce
from typing import Any, Callable, Dict, List, Optional, Tuple


def _safe_product(lst, initial=1):
    if not lst:
        return initial
    result = initial
    for x in lst:
        result *= x
    return result


def _coerce_output(result):
    if result is None:
        return None
    if isinstance(result, tuple):
        result = list(result)
    if not isinstance(result, list):
        return None
    out = []
    for v in result:
        if isinstance(v, bool):
            return None
        if isinstance(v, int):
            out.append(v)
        elif isinstance(v, float) and v.is_integer():
            out.append(int(v))
        else:
            return None
    return out


# ============================================================
# PRIMITIVE OPERATIONS
# ============================================================

def _id(xs):
    return list(xs)

def _rev(xs):
    return list(reversed(xs))

def _sort_asc(xs):
    return sorted(xs)

def _sort_desc(xs):
    return sorted(xs, reverse=True)

def _dedup_first(xs):
    seen = set()
    result = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result

def _dedup_last(xs):
    seen = set()
    result = []
    for x in reversed(xs):
        if x not in seen:
            seen.add(x)
            result.append(x)
    return list(reversed(result))

def _unique(xs):
    c = Counter(xs)
    return [x for x in xs if c[x] == 1]

def _nonzero(xs):
    return [x for x in xs if x != 0]

def _positive(xs):
    return [x for x in xs if x > 0]

def _odds(xs):
    return [x for x in xs if x % 2 != 0]

def _evens(xs):
    return [x for x in xs if x % 2 == 0]

def _prod(xs):
    return [_safe_product(xs, 1)]

def _sum_val(xs):
    return [sum(xs)]

def _min_v(xs):
    return [min(xs)] if xs else []

def _max_v(xs):
    return [max(xs)] if xs else []

def _count_unique(xs):
    return [len(set(xs))]

def _count_elems(xs):
    return [len(xs)]

def _count_nonzero(xs):
    return [sum(1 for x in xs if x != 0)]

def _count_odd(xs):
    return [sum(1 for x in xs if x % 2 != 0)]

def _count_even(xs):
    return [sum(1 for x in xs if x % 2 == 0)]

def _count_max_count(xs):
    if not xs:
        return [0]
    return [Counter(xs).most_common(1)[0][1]]

def _freq_count(xs):
    c = Counter(xs)
    seen = set()
    result = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            result.append(c[x])
    return result

def _freq_sorted(xs):
    c = Counter(xs)
    return [c[k] for k in sorted(c)]

def _sort_unique_by_count_desc(xs):
    c = Counter(xs)
    return sorted(set(xs), key=lambda x: (-c[x], x))

def _cumsum(xs):
    result = []
    s = 0
    for x in xs:
        s += x
        result.append(s)
    return result

def _count_leq(xs, n):
    return [sum(1 for x in xs if x <= n)]

def _count_lt(xs, n):
    return [sum(1 for x in xs if x < n)]

def _count_ge(xs, n):
    return [sum(1 for x in xs if x >= n)]

def _count_gt(xs, n):
    return [sum(1 for x in xs if x > n)]

def _count_equal(xs, n):
    return [sum(1 for x in xs if x == n)]

def _slice_first_n(xs, n):
    return xs[:n]

def _slice_last_n(xs, n):
    return xs[-n:] if n > 0 else []

def _slice_skip(xs, step):
    return xs[::step]

def _rotate_left(xs):
    if len(xs) <= 1:
        return list(xs)
    return xs[1:] + xs[:1]

def _rotate_right(xs):
    if len(xs) <= 1:
        return list(xs)
    return xs[-1:] + xs[:-1]

def _rotate_left_k(xs, k):
    if not xs:
        return []
    n = len(xs)
    k = k % n
    return xs[k:] + xs[:k]

def _rotate_right_k(xs, k):
    if not xs:
        return []
    n = len(xs)
    k = k % n
    return xs[-k:] + xs[:-k] if k > 0 else list(xs)

def _prepend_const(xs, v):
    return [v] + list(xs)

def _append_const(xs, v):
    return list(xs) + [v]

def _prepend_rev(xs, v):
    return [v] + list(reversed(xs))

def _append_rev(xs, v):
    return list(xs) + [v]

def _prepend_last_elem(xs):
    if not xs:
        return list(xs)
    return [xs[-1]] + list(xs)

def _append_first_elem(xs):
    if not xs:
        return list(xs)
    return list(xs) + [xs[0]]

def _prepend_last_two(xs):
    if len(xs) < 2:
        return list(xs)
    return [xs[-2], xs[-1]] + list(xs)

def _append_first_two(xs):
    if len(xs) < 2:
        return list(xs) + list(xs)
    return list(xs) + [xs[0], xs[1]]

def _remove_at_idx(xs, i):
    if 0 <= i < len(xs):
        return xs[:i] + xs[i+1:]
    return list(xs)

def _remove_first_occurrence(xs, val):
    result = list(xs)
    try:
        result.remove(val)
    except ValueError:
        pass
    return result

def _remove_last_occurrence(xs, val):
    for i in range(len(xs) - 1, -1, -1):
        if xs[i] == val:
            return xs[:i] + xs[i+1:]
    return list(xs)

def _remove_middle(xs):
    n = len(xs)
    if n <= 1:
        return list(xs)
    mid = n // 2
    return xs[:mid] + xs[mid+1:]

def _filter_nonzero_then_sort(xs):
    return sorted(x for x in xs if x != 0)

def _filter_positive_then_sort(xs):
    return sorted(x for x in xs if x > 0)

def _filter_odd_then_sort(xs):
    return sorted(x for x in xs if x % 2 != 0)

def _dedup_then_sort(xs):
    return sorted(set(xs))

def _dedup_then_sort_desc(xs):
    return sorted(set(xs), reverse=True)

def _sort_desc_then_dedup(xs):
    return sorted(set(xs), reverse=True)

def _elem_rank(xs):
    if not xs:
        return []
    s = sorted(xs)
    return [s.index(x) + 1 for x in xs]

def _elem_count_le(xs):
    return [sum(1 for v in xs if v <= x) for x in xs]

def _elem_count_lt(xs):
    return [sum(1 for v in xs if v < x) for x in xs]

def _elem_count_ge(xs):
    return [sum(1 for v in xs if v >= x) for x in xs]

def _elem_count_gt(xs):
    return [sum(1 for v in xs if v > x) for x in xs]

def _count_missing_in_0_to_max(xs):
    if not xs:
        return [0]
    mx = max(xs)
    present = set(xs)
    return [mx + 1 - len([x for x in range(mx + 1) if x in present])]

def _filter_greater_than_min(xs):
    if not xs:
        return []
    mn = min(xs)
    return [x for x in xs if x > mn]

def _filter_less_than_max(xs):
    if not xs:
        return []
    mx = max(xs)
    return [x for x in xs if x < mx]

def _filter_between_min_max(xs):
    if not xs:
        return []
    mn, mx = min(xs), max(xs)
    return [x for x in xs if mn < x < mx]

def _swap_first_last(xs):
    if len(xs) <= 1:
        return list(xs)
    result = list(xs)
    result[0], result[-1] = result[-1], result[0]
    return result

def _keep_first_n_unique(xs, n):
    seen = set()
    result = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            result.append(x)
            if len(seen) >= n:
                break
    return result

def _rotate_by_first_element(xs):
    if not xs:
        return []
    n = len(xs)
    if n <= 1:
        return list(xs)
    k = xs[0] % n
    return xs[k:] + xs[:k]

def _rotate_by_last_element(xs):
    if not xs:
        return []
    n = len(xs)
    if n <= 1:
        return list(xs)
    k = xs[-1] % n
    return xs[k:] + xs[:k]

def _rotate_left_count_nonzero(xs):
    if not xs:
        return []
    n = len(xs)
    k = sum(1 for x in xs if x != 0) % n
    return xs[k:] + xs[:k]

def _rotate_left_count_zero(xs):
    if not xs:
        return []
    n = len(xs)
    k = sum(1 for x in xs if x == 0) % n
    return xs[k:] + xs[:k]


# ============================================================
# SEARCH HELPERS
# ============================================================

def _apply_primitive(func, xs):
    try:
        result = func(xs)
        return _coerce_output(result)
    except Exception:
        return None


def _try_program(program, inputs, outputs):
    for inp, expected in zip(inputs, outputs):
        try:
            got = _coerce_output(program(list(inp)))
            if got != list(expected):
                return False
        except Exception:
            return False
    return True


def _score_program(program, inputs, outputs):
    correct = 0
    for inp, expected in zip(inputs, outputs):
        try:
            got = _coerce_output(program(list(inp)))
            if got is not None and got == list(expected):
                correct += 1
        except Exception:
            pass
    return correct / max(len(inputs), 1)


# ============================================================
# PATTERN-BASED DETECTION
# ============================================================

def _detect_const_output(inputs, outputs):
    if all(o == outputs[0] for o in outputs):
        return [(f"constant_{outputs[0][:5]}", lambda xs, o=outputs[0]: list(o))]
    return []


def _detect_identity(inputs, outputs):
    if all(o == i for i, o in zip(inputs, outputs)):
        return [("identity", lambda xs: list(xs))]
    return []


def _detect_rotation(inputs, outputs):
    results = []
    for inp, out in zip(inputs, outputs):
        n = len(inp)
        if n == 0:
            continue
        for k in range(n):
            rotated = inp[k:] + inp[:k]
            if rotated == out:
                results.append((f"rotate_left_{k}", lambda xs, _k=k: xs[_k:] + xs[:_k] if _k > 0 else list(xs)))
            rotated_r = inp[-k:] + inp[:-k] if k > 0 else list(inp)
            if rotated_r == out:
                results.append((f"rotate_right_{k}", lambda xs, _k=k: xs[-_k:] + xs[:-_k] if _k > 0 else list(xs)))
    return results


def _detect_slice(inputs, outputs):
    results = []
    for inp, out in zip(inputs, outputs):
        n_in = len(inp)
        n_out = len(out)
        if n_out <= n_in:
            for n in range(n_out, n_in + 1):
                if inp[:n] == out:
                    results.append((f"slice_first_{n}", lambda xs, _n=n: xs[:_n]))
            for n in range(n_out, n_in + 1):
                if inp[-n:] == out:
                    results.append((f"slice_last_{n}", lambda xs, _n=n: xs[-_n:]))
            for start in range(n_in):
                for end in range(start + 1, n_in + 1):
                    if inp[start:end] == out:
                        results.append((f"slice_{start}_{end}", lambda xs, _s=start, _e=end: xs[_s:_e]))
    return results


def _detect_remove(inputs, outputs):
    results = []
    for inp, out in zip(inputs, outputs):
        n_in = len(inp)
        n_out = len(out)
        if n_in - n_out == 1:
            for i in range(n_in):
                candidate = inp[:i] + inp[i+1:]
                if candidate == out:
                    results.append((f"remove_idx_{i}", lambda xs, _i=i: xs[:_i] + xs[_i+1:]))
    return results


def _detect_const_prefix_suffix(inputs, outputs):
    results = []
    if not inputs or not outputs:
        return results

    # Check constant prefix
    prefix_len = len(outputs[0]) - len(inputs[0])
    if prefix_len >= 0:
        prefix = outputs[0][:prefix_len]
        fn = lambda xs, _p=prefix: list(_p) + list(xs)
        if _try_program(fn, inputs, outputs):
            results.append(("const_prefix", fn))

    # Check constant suffix
    if len(outputs[0]) >= len(inputs[0]):
        suffix = outputs[0][len(inputs[0]):]
        fn = lambda xs, _s=suffix: list(xs) + list(_s)
        if _try_program(fn, inputs, outputs):
            results.append(("const_suffix", fn))

    # Check prefix + input + suffix
    if prefix_len > 0:
        suffix = outputs[0][len(inputs[0]):]
        fn = lambda xs, _p=prefix, _s=suffix: list(_p) + list(xs) + list(_s)
        if _try_program(fn, inputs, outputs):
            results.append(("const_prefix_suffix", fn))

    return results


def _detect_elementwise(inputs, outputs):
    results = []
    for inp, out in zip(inputs, outputs):
        if len(inp) != len(out):
            continue
        if len(inp) == 0:
            continue

        # Check y = a*x + b
        non_zero = [(x, y) for x, y in zip(inp, out) if x != 0]
        if non_zero:
            x1, y1 = non_zero[0]
            for i in range(1, min(3, len(non_zero))):
                x2, y2 = non_zero[i]
                if x2 != x1 and (y2 - y1) % (x2 - x1) == 0:
                    a = (y2 - y1) // (x2 - x1)
                    b = y1 - a * x1
                    if all(y == a * x + b for x, y in zip(inp, out)):
                        results.append((f"elem_{a}x+{b}", lambda xs, _a=a, _b=b: [_a*x + _b for x in xs]))

        # Check y = x + b
        diffs = [y - x for x, y in zip(inp, out)]
        if all(d == diffs[0] for d in diffs):
            results.append((f"elem_+{diffs[0]}", lambda xs, _b=diffs[0]: [x + _b for x in xs]))

        # Check y = a*x
        if all(y == 0 or (y * inp[0] == x * out[0]) for x, y in zip(inp, out)):
            if inp[0] != 0:
                a = out[0] / inp[0] if inp[0] else 0
                if isinstance(a, float) and a == int(a):
                    a = int(a)
                    if all(y == a * x for x, y in zip(inp, out)):
                        results.append((f"elem_{a}x", lambda xs, _a=a: [_a*x for x in xs]))

        # Check y = x
        if all(y == x for x, y in zip(inp, out)):
            results.append(("elem_identity", lambda xs: list(xs)))

        # Check y = -x + b
        sums = [x + y for x, y in zip(inp, out)]
        if all(s == sums[0] for s in sums):
            results.append((f"elem_rev_+{sums[0]}", lambda xs, _b=sums[0]: [_b - x for x in xs]))

    return results


def _detect_frequency(inputs, outputs):
    results = []
    all_match = True
    for inp, out in zip(inputs, outputs):
        c = Counter(inp)
        seen = set()
        freqs = []
        for x in inp:
            if x not in seen:
                seen.add(x)
                freqs.append(c[x])
        if freqs != out:
            all_match = False
            break
    if all_match:
        results.append(("freq_count", lambda xs: _freq_count(xs)))

    all_match = True
    for inp, out in zip(inputs, outputs):
        c = Counter(inp)
        expected = [c[k] for k in sorted(c)]
        if expected != out:
            all_match = False
            break
    if all_match:
        results.append(("freq_sorted", lambda xs: _freq_sorted(xs)))

    return results


def _detect_reduction(inputs, outputs):
    results = []
    for inp, out in zip(inputs, outputs):
        if len(out) == 1 and len(inp) >= 1:
            val = out[0]
            if _safe_product(inp, 1) == val:
                results.append(("reduce_product", lambda xs: [_safe_product(xs, 1)]))
            if sum(inp) == val:
                results.append(("reduce_sum", lambda xs: [sum(xs)]))
            if min(inp) == val:
                results.append(("reduce_min", lambda xs: [min(xs)]))
            if max(inp) == val:
                results.append(("reduce_max", lambda xs: [max(xs)]))
            if len(set(inp)) == val:
                results.append(("reduce_unique_count", lambda xs: [len(set(xs))]))
            # Count of specific value
            for v in set(inp):
                if sum(1 for x in inp if x == v) == val:
                    results.append((f"count_equal_{v}", lambda xs, _v=v: [sum(1 for x in xs if x == _v)]))
    return results


def _detect_sort(inputs, outputs):
    results = []
    for inp, out in zip(inputs, outputs):
        if sorted(inp) == out:
            results.append(("sort_asc", lambda xs: sorted(xs)))
        if sorted(inp, reverse=True) == out:
            results.append(("sort_desc", lambda xs: sorted(xs, reverse=True)))
    return results


def _detect_dedup(inputs, outputs):
    results = []
    for inp, out in zip(inputs, outputs):
        seen = set()
        deduped = []
        for x in inp:
            if x not in seen:
