                deduped.append(x)
        if deduped == out:
            results.append(("dedup_first", lambda xs: _dedup_first(xs)))
    return results


def _detect_filter(inputs, outputs):
    results = []

    fn_nonzero = lambda xs: [x for x in xs if x != 0]
    if _try_program(fn_nonzero, inputs, outputs):
