def _detect_c109_pattern(inputs, outputs):
    """c109: single element -> identity, multiple -> product."""
    single_match = all(
        len(inp) == 1 and out == inp
        for inp, out in zip(inputs, outputs) if len(inp) == 1
    )
    multi_match = all(
        len(inp) > 1 and out == [_safe_product(inp)]
        for inp, out in zip(inputs, outputs) if len(inp) > 1
    )
    if single_match and multi_match:
        return [("c109_pattern", lambda xs: [_safe_product(xs, 1)] if len(xs) > 1 else list(xs))]
    return []


def _detect_c118_pattern(inputs, outputs):
    """c118: rotation by first element mod len."""
    if not inputs:
