        n = len(inp)
        if n <= 1:
            if inp != out:
                all_match = False
                break
            continue
        k = inp[0] % n
        expected = inp[k:] + inp[:k]
        if expected != out:
            all_match = False
            break
    if all_match:
        return [("rotate_by_first_mod", lambda xs: _rotate_left_by_k(xs, xs[0] % len(xs)) if xs else [])]
