def _detect_c250_pattern(inputs, outputs):
    """c250: sort unique elements by count descending, preserve duplicates."""
    if not inputs:
        return []
    all_match = True
    for inp, out in zip(inputs, outputs):
        c = Counter(inp)
        sorted_keys = sorted(c.keys(), key=lambda x: (-c[x], x))
        expected = []
        for k in sorted_keys:
            expected.extend([k] * c[k])
        if expected != out:
            all_match = False
            break
    if all_match:
        return [("c250_pattern", lambda xs: _sort_unique_by_count_desc(xs))]
    return []


def _detect_c097_pattern(inputs, outputs):
    """c097: constant_prefix + input + constant_suffix."""
    if not inputs:
        return []
    # Find common prefix (same for all examples)
    for plen in range(min(len(outputs[0]), len(inputs[0])) + 1):
        prefix = outputs[0][:plen]
        suffix_start = len(outputs[0]) - (len(outputs[0]) - len(inputs[0]))
        # Check if all outputs = prefix + input
        all_match = True
        for inp, out in zip(inputs, outputs):
            if not out[:plen] == prefix:
                all_match = False
                break
            suffix_len = len(out) - plen - len(inp)
            if suffix_len < 0 or not out[plen:plen+len(inp)] == inp:
                all_match = False
                break
            suffix = out[plen+len(inp):]
            if plen > 0 and out[:plen] != prefix:
                all_match = False
                break
        if all_match and plen > 0:
            suffix = outputs[0][plen + len(inputs[0]):]
            return [(f"prefix_{plen}", lambda xs, _p=prefix, _s=suffix: list(_p) + list(xs) + list(_s))]
    return []


