        expected = [c[k] for k in sorted(c)]
        if expected != out:
            all_match = False
            break
    if all_match:
        results.append(("freq_sorted", lambda xs: _freq_sorted(xs)))

    return results


def _detect_reduction(inputs, outputs):
    results = []
    for inp, out in zip(inputs, outputs):
        if len(out) == 1 and len(inp) >= 1:
            val = out[0]
            if _safe_product(inp, 1) == val:
                results.append(("reduce_product", lambda xs: [_safe_product(xs, 1)]))
            if sum(inp) == val:
                results.append(("reduce_sum", lambda xs: [sum(xs)]))
            if min(inp) == val:
                results.append(("reduce_min", lambda xs: [min(xs)]))
            if max(inp) == val:
                results.append(("reduce_max", lambda xs: [max(xs)]))
            if len(set(inp)) == val:
                results.append(("reduce_unique_count", lambda xs: [len(set(xs))]))
            # Count of specific value
            for v in set(inp):
                if sum(1 for x in inp if x == v) == val:
                    results.append((f"count_equal_{v}", lambda xs, _v=v: [sum(1 for x in xs if x == _v)]))
    return results


def _detect_sort(inputs, outputs):
    results = []
    for inp, out in zip(inputs, outputs):
        if sorted(inp) == out:
            results.append(("sort_asc", lambda xs: sorted(xs)))
        if sorted(inp, reverse=True) == out:
            results.append(("sort_desc", lambda xs: sorted(xs, reverse=True)))
    return results


def _detect_dedup(inputs, outputs):
    results = []
    for inp, out in zip(inputs, outputs):
        seen = set()
        deduped = []
        for x in inp:
            if x not in seen:
                seen.add(x)
                deduped.append(x)
        if deduped == out:
            results.append(("dedup_first", lambda xs: _dedup_first(xs)))
    return results


def _detect_filter(inputs, outputs):
    results = []

    fn_nonzero = lambda xs: [x for x in xs if x != 0]
    if _try_program(fn_nonzero, inputs, outputs):
        results.append(("filter_nonzero", fn_nonzero))

    fn_positive = lambda xs: [x for x in xs if x > 0]
    if _try_program(fn_positive, inputs, outputs):
        results.append(("filter_positive", fn_positive))

    fn_odds = lambda xs: [x for x in xs if x % 2 != 0]
    if _try_program(fn_odds, inputs, outputs):
        results.append(("filter_odds", fn_odds))

    fn_evens = lambda xs: [x for x in xs if x % 2 == 0]
    if _try_program(fn_evens, inputs, outputs):
        results.append(("filter_evens", fn_evens))

    fn_greater_min = lambda xs: _filter_greater_than_min(xs)
    if _try_program(fn_greater_min, inputs, outputs):
        results.append(("filter_greater_than_min", fn_greater_min))

    fn_less_max = lambda xs: _filter_less_than_max(xs)
    if _try_program(fn_less_max, inputs, outputs):
        results.append(("filter_less_than_max", fn_less_max))

    return results


def _detect_c109_pattern(inputs, outputs):
    """c109: single element -> identity, multiple -> product."""
    single_match = all(
        len(inp) == 1 and out == inp
        for inp, out in zip(inputs, outputs) if len(inp) == 1
    )
    multi_match = all(
        len(inp) > 1 and out == [_safe_product(inp)]
        for inp, out in zip(inputs, outputs) if len(inp) > 1
    )
    if single_match and multi_match:
        return [("c109_pattern", lambda xs: [_safe_product(xs, 1)] if len(xs) > 1 else list(xs))]
    return []


def _detect_c118_pattern(inputs, outputs):
    """c118: rotation by first element mod len."""
    if not inputs:
        return []
    all_match = True
    for inp, out in zip(inputs, outputs):
        if not inp:
            continue
        n = len(inp)
        if n <= 1:
            if inp != out:
                all_match = False
                break
            continue
        k = inp[0] % n
        expected = inp[k:] + inp[:k]
        if expected != out:
            all_match = False
            break
    if all_match:
        return [("rotate_by_first_mod", lambda xs: _rotate_left_by_k(xs, xs[0] % len(xs)) if xs else [])]
    return []


def _detect_c114_pattern(inputs, outputs):
    """c114: [max] + reversed(input)."""
    if not inputs:
        return []
    all_match = True
    for inp, out in zip(inputs, outputs):
        if not inp:
            continue
        expected = [max(inp)] + list(reversed(inp))
        if expected != out:
            all_match = False
            break
    if all_match:
        return [("prepend_max_rev", lambda xs: [max(xs)] + list(reversed(xs)) if xs else list(xs))]
    return []


def _detect_c022_pattern(inputs, outputs):
    """c022: [first, max] + rest_of_input."""
    if not inputs:
        return []
    all_match = True
    for inp, out in zip(inputs, outputs):
        if not inp:
            continue
        expected = [inp[0], max(inp)] + inp[1:]
        if expected != out:
            all_match = False
            break
    if all_match:
        return [("c022_pattern", lambda xs: [xs[0], max(xs)] + xs[1:] if xs else [])]
    return []


def _detect_c250_pattern(inputs, outputs):
    """c250: sort unique elements by count descending, preserve duplicates."""
    if not inputs:
        return []
    all_match = True
    for inp, out in zip(inputs, outputs):
        c = Counter(inp)
        sorted_keys = sorted(c.keys(), key=lambda x: (-c[x], x))
        expected = []
        for k in sorted_keys:
            expected.extend([k] * c[k])
        if expected != out:
            all_match = False
            break
    if all_match:
        return [("c250_pattern", lambda xs: _sort_unique_by_count_desc(xs))]
    return []


def _detect_c097_pattern(inputs, outputs):
    """c097: constant_prefix + input + constant_suffix."""
    if not inputs:
        return []
    # Find common prefix (same for all examples)
    for plen in range(min(len(outputs[0]), len(inputs[0])) + 1):
        prefix = outputs[0][:plen]
        suffix_start = len(outputs[0]) - (len(outputs[0]) - len(inputs[0]))
        # Check if all outputs = prefix + input
        all_match = True
        for inp, out in zip(inputs, outputs):
            if not out[:plen] == prefix:
                all_match = False
                break
            suffix_len = len(out) - plen - len(inp)
            if suffix_len < 0 or not out[plen:plen+len(inp)] == inp:
                all_match = False
                break
            suffix = out[plen+len(inp):]
            if plen > 0 and out[:plen] != prefix:
                all_match = False
                break
        if all_match and plen > 0:
            suffix = outputs[0][plen + len(inputs[0]):]
            return [(f"prefix_{plen}", lambda xs, _p=prefix, _s=suffix: list(_p) + list(xs) + list(_s))]
    return []


def _detect_c130_pattern(inputs, outputs):
    """c130: remove element at index n//2."""
    if not inputs:
        return []
    all_match = True
    for inp, out in zip(inputs, outputs):
        n = len(inp)
        if n <= 1:
            if inp != out:
                all_match = False
                break
            continue
        mid = n // 2
        expected = inp[:mid] + inp[mid+1:]
        if expected != out:
            all_match = False
            break
    if all_match:
        return [("remove_middle", lambda xs: _remove_middle(xs))]
    return []


