def _detect_c165_pattern(inputs, outputs):
    """c165: remove even-positioned unique elements."""
    if not inputs:
        return []
    all_match = True
    for inp, out in zip(inputs, outputs):
        seen = set()
        deduped = []
        for x in inp:
            if x not in seen:
                seen.add(x)
                deduped.append(x)
        # Keep only elements at odd positions (0-indexed) in deduped list
        kept = [x for i, x in enumerate(deduped) if i % 2 == 1]
        if kept != out:
            all_match = False
            break
    if all_match:
        def fn(xs):
            seen = set()
            deduped = []
            for x in xs:
                if x not in seen:
                    seen.add(x)
                    deduped.append(x)
            return [x for i, x in enumerate(deduped) if i % 2 == 1]
        return [("c165_pattern", fn)]
    return []


