def solve_listfn(examples, K=5):
    """
    Solve a List Functions task.

    Args:
        examples: list of (input_list, output_list) pairs
        K: number of top programs to return if no exact match

    Returns:
        dict with "success" (bool) and "program" (source string or callable)
    """
    inputs = [inp for inp, _ in examples]
    outputs = [out for _, out in examples]

    # Try pattern-based detection
    detection_funcs = [
        _detect_const_output,
        _detect_identity,
        _detect_c109_pattern,
        _detect_c118_pattern,
        _detect_c114_pattern,
        _detect_c022_pattern,
        _detect_c250_pattern,
        _detect_c097_pattern,
        _detect_c130_pattern,
        _detect_c165_pattern,
        _detect_c245_pattern,
        _detect_c241_pattern,
        _detect_c203_pattern,
        _detect_rotation,
        _detect_slice,
        _detect_remove,
        _detect_const_prefix_suffix,
        _detect_elementwise,
        _detect_frequency,
        _detect_reduction,
        _detect_sort,
        _detect_dedup,
        _detect_filter,
    ]

    for detect_fn in detection_funcs:
        try:
            candidates = detect_fn(inputs, outputs)
            for name, fn in candidates:
                if _try_program(fn, inputs, outputs):
                    return {"success": True, "program": fn}
        except Exception:
            continue

    # Search over unary primitives
    unary_primitives = {
        'id': _id, 'rev': _rev, 'sort_asc': _sort_asc, 'sort_desc': _sort_desc,
        'dedup_first': _dedup_first, 'dedup_last': _dedup_last,
        'unique': _unique, 'nonzero': _nonzero, 'positive': _positive,
        'odds': _odds, 'evens': _evens,
        'prod': _prod, 'sum_val': _sum_val, 'min_v': _min_v, 'max_v': _max_v,
        'count_unique': _count_unique, 'count_elems': _count_elems,
        'count_nonzero': _count_nonzero, 'count_odd': _count_odd,
        'count_even': _count_even, 'count_max_count': _count_max_count,
        'freq_count': _freq_count, 'freq_sorted': _freq_sorted,
        'sort_unique_by_count_desc': _sort_unique_by_count_desc,
        'cumsum': _cumsum,
        'filter_nonzero_then_sort': _filter_nonzero_then_sort,
        'filter_positive_then_sort': _filter_positive_then_sort,
        'filter_odd_then_sort': _filter_odd_then_sort,
        'dedup_then_sort': _dedup_then_sort, 'dedup_then_sort_desc': _dedup_then_sort_desc,
        'elem_rank': _elem_rank, 'elem_count_le': _elem_count_le,
        'elem_count_lt': _elem_count_lt, 'elem_count_ge': _elem_count_ge,
        'elem_count_gt': _elem_count_gt,
        'count_missing_in_0_to_max': _count_missing_in_0_to_max,
        'filter_greater_than_min': _filter_greater_than_min,
        'filter_less_than_max': _filter_less_than_max,
        'filter_between_min_max': _filter_between_min_max,
        'swap_first_last': _swap_first_last,
        'prepend_last_elem': _prepend_last_elem,
        'append_first_elem': _append_first_elem,
        'prepend_last_two': _prepend_last_two,
        'append_first_two': _append_first_two,
        'rotate_by_first_element': _rotate_by_first_element,
        'rotate_by_last_element': _rotate_by_last_element,
        'rotate_left_count_nonzero': _rotate_left_count_nonzero,
        'rotate_left_count_zero': _rotate_left_count_zero,
    }

    for name, func in unary_primitives.items():
        if _try_program(func, inputs, outputs):
            return {"success": True, "program": func}

    # Search over parametric primitives
    param_values = list(range(-10, 21))

    # Generate parametric functions
    all_candidates = []

    for p in param_values:
        all_candidates.append((f"elem_+{p}", lambda xs, _v=p: [_v + x for x in xs]))
        all_candidates.append((f"elem_-{p}", lambda xs, _v=p: [x - _v for x in xs]))
        all_candidates.append((f"elem_*{p}", lambda xs, _v=p: [x * _v for x in xs]))
        all_candidates.append((f"slice_first_{p}", lambda xs, _n=p: xs[:_n]))
        all_candidates.append((f"slice_last_{p}", lambda xs, _n=p: xs[-_n:] if _n > 0 else []))
        all_candidates.append((f"rotate_left_{p}", lambda xs, _k=p: xs[_k:] + xs[:_k] if _k > 0 else list(xs)))
        all_candidates.append((f"rotate_right_{p}", lambda xs, _k=p: xs[-_k:] + xs[:-_k] if _k > 0 else list(xs)))
        all_candidates.append((f"remove_idx_{p}", lambda xs, _i=p: xs[:_i] + xs[_i+1:]))
        all_candidates.append((f"prepend_{p}", lambda xs, _v=p: [_v] + list(xs)))
        all_candidates.append((f"append_{p}", lambda xs, _v=p: list(xs) + [_v]))
        all_candidates.append((f"count_le_{p}", lambda xs, _n=p: [sum(1 for x in xs if x <= _n)]))
        all_candidates.append((f"count_lt_{p}", lambda xs, _n=p: [sum(1 for x in xs if x < _n)]))
        all_candidates.append((f"count_ge_{p}", lambda xs, _n=p: [sum(1 for x in xs if x >= _n)]))
        all_candidates.append((f"count_gt_{p}", lambda xs, _n=p: [sum(1 for x in xs if x > _n)]))
        all_candidates.append((f"count_eq_{p}", lambda xs, _n=p: [sum(1 for x in xs if x == _n)]))
        all_candidates.append((f"rotate_left_mod_{p}", lambda xs, _k=p: _rotate_left_k(xs, p)))

    # Try parametric functions
    for name, fn in all_candidates:
        if _try_program(fn, inputs, outputs):
            return {"success": True, "program": fn}

    # Two-primitive compositions with parametric functions
    unary_funcs = list(unary_primitives.values())

    for param_fn_name, param_fn in all_candidates:
        for unary_fn in unary_funcs:
            # unary -> parametric
            def compose_up(u, p, xs):
                inter = _apply_primitive(u, xs)
                if inter is None:
                    return None
                return _coerce_output(p(inter))
            fn = lambda xs, _u=unary_fn, _p=param_fn: compose_up(_u, _p, xs)
            if _try_program(fn, inputs, outputs):
                return {"success": True, "program": fn}

            # parametric -> unary
            def compose_pp(p, u, xs):
                inter = _coerce_output(p(xs))
                if inter is None:
                    return None
                return _coerce_output(u(inter))
            fn = lambda xs, _p=param_fn, _u=unary_fn: compose_pp(_p, _u, xs)
            if _try_program(fn, inputs, outputs):
                return {"success": True, "program": fn}

    # Two-primitive compositions with unary functions
    for i, f1 in enumerate(unary_funcs):
        for j, f2 in enumerate(unary_funcs):
            if i == j:
                continue
            def compose_uu(f1, f2, xs):
                inter = _apply_primitive(f1, xs)
                if inter is None:
                    return None
                return _apply_primitive(f2, inter)
            fn = lambda xs, _f1=f1, _f2=f2: compose_uu(_f1, _f2, xs)
            if _try_program(fn, inputs, outputs):
                return {"success": True, "program": fn}

    # Three-primitive compositions (limited search)
    top_primitives = sorted(
        [("unary_" + n, f) for n, f in unary_primitives.items()],
        key=lambda x: _score_program(x[1], inputs, outputs),
        reverse=True
    )[:10]

    for f1_name, f1 in top_primitives[:5]:
        for f2_name, f2 in top_primitives[:5]:
            for f3_name, f3 in top_primitives[:5]:
                def compose_3(f1, f2, f3, xs):
                    inter1 = _apply_primitive(f1, xs)
                    if inter1 is None:
                        return None
                    inter2 = _apply_primitive(f2, inter1)
                    if inter2 is None:
                        return None
                    return _apply_primitive(f3, inter2)
                fn = lambda xs, _f1=f1, _f2=f2, _f3=f3: compose_3(_f1, _f2, _f3, xs)
                if _try_program(fn, inputs, outputs):
                    return {"success": True, "program": fn}

    # Score-based: return top-K best programs
    scored = []
    for name, fn in all_candidates:
        try:
            score = _score_program(fn, inputs, outputs)
            scored.append((score, fn, name))
        except Exception:
            pass

    for name, func in unary_primitives.items():
        try:
            score = _score_program(func, inputs, outputs)
            scored.append((score, func, name))
        except Exception:
            pass

    for i, (n1, f1) in enumerate(top_primitives[:10]):
        for j, (n2, f2) in enumerate(top_primitives[:10]):
            try:
                def compose_scored(f1, f2, xs):
                    inter = _apply_primitive(f1, xs)
                    if inter is None:
                        return None
                    return _apply_primitive(f2, inter)
                fn = lambda xs, _f1=f1, _f2=f2: compose_scored(_f1, _f2, xs)
                score = _score_program(fn, inputs, outputs)
                scored.append((score, fn, f"{n1}_then_{n2}"))
            except Exception:
                pass

    scored.sort(key=lambda x: x[0], reverse=True)

    if scored and scored[0][0] >= 1.0:
        return {"success": True, "program": scored[0][1]}

    programs = scored[:K]
    if programs:
        return {
            "success": False,
            "program": programs[0][1],
            "top_k": [{"score": s, "name": n} for s, _, n in programs]
        }

    return {"success": False, "program": lambda xs: list(xs)}


